// obfScore — deterministic PowerShell obfuscation score (no AI).
// Allowlist: approved admin script paths downgrade the score (lab constant; prod: signed-script allowlist).
function obfScore(cmd) {
  const s = String(cmd || '').toLowerCase();
  if (!s) return { score: 0, reasons: [] };
  const ALLOW = ['c:\\scripts\\backup.ps1', 'c:\\scripts\\patch.ps1'];
  const checks = [
    [/-enc|-encodedcommand|frombase64string/, 'base64/encoded payload'],
    [/iex|invoke-expression/, 'invoke-expression'],
    [/downloadstring|downloadfile|downloaddata|net\\.webclient|start-bitstransfer/, 'download cradle'],
    [/-nop|-noni|-noprofile|-w(indowstyle)?\\s+hidden/, 'hidden / non-interactive'],
    [/amsiscanbuffer|amsiutils|amsi bypass/, 'AMSI bypass attempt'],
    [/\^+[a-z0-9]|`%|%\^/, 'caret/percent obfuscation'],
    [/invoke-|new-object\\s+-com/, 'COM/automation execution'],
  ];
  let reasons = checks.filter(function (c) { return c[0].test(s); }).map(function (c) { return c[1]; });
  if (/[a-z0-9+\\/]{100,}={0,2}/.test(s)) reasons.push('long base64 blob');
  let allowlisted = ALLOW.filter(function (a) { return s.indexOf(a.toLowerCase()) !== -1; });
  if (allowlisted.length) return { score: 0, reasons: ['allowlisted admin script: ' + allowlisted[0]] };
  return { score: Math.min(10, reasons.length), reasons: reasons };
}

