// ResponseGate.v3 — deterministic risk + response gates. Propose only, never executes.
// B1: TI contributions are computed PER indicator; the MAXIMUM across indicators
// is used (never summed — avoids score inflation when several indicators hit).
// Source guards: a record object with no signal scores 0 (unknown stays unknown).
// Weights otherwise identical to v2 (web +15, public +5, obfuscation +10,
// impossible-travel +40, cloud-identity sensitive/denied/public).
const e = $input.first().json;
const tis = Array.isArray(e.threat_intel) ? e.threat_intel.filter((t) => t && t.indicator) : [];
const numOr = (x) => (typeof x === 'number' && isFinite(x)) ? x : 0;
function tiContrib(t) {
  const s = (t && t.sources) || {};
  let c = 0;
  const v = s.virustotal;
  if (v && typeof v === 'object') c += Math.min(30, numOr(v.malicious) * 3 + numOr(v.suspicious));
  const a = s.abuseipdb;
  if (a && typeof a === 'object') c += Math.min(25, Math.round(numOr(a.confidence) / 4));
  const uh = s.urlhaus;
  if (uh && typeof uh === 'object' && /malware|phish/.test(uh.url_status || '')) c += 15;
  const ox = s.otx;
  if (ox && typeof ox === 'object' && numOr(ox.pulses) > 0) c += 10;
  return c;
}
let tiMax = 0;
tis.forEach((t) => { const c = tiContrib(t); if (c > tiMax) tiMax = c; });
// weight v2 (2026-10-09): +15 web-exploit class (DBIR #1 initial vector), +5 public src, +10 obfuscation>=3
let risk = 10 + (e.rule_level || 0) * 2;
const _at = (function(){ try { return String($('NormalizeAlert').first().json.attack_type || ''); } catch (x) { return ''; } })(); // cross-node ref: immune to merge shape
if (_at === 'web') risk += 15;
const _pub = !/^(10[.]|192[.]168[.]|172[.](1[6-9]|2[0-9]|3[01])[.]|127[.]|$)/.test(e.src_ip || '');
if (_pub) risk += 5;
const _obf = (function(){ try { return Number($('NormalizeAlert').first().json.observables.obf_score) || 0; } catch (x) { return 0; } })();
if (_obf >= 3) risk += 10;
risk += tiMax;
if (e.evidence && e.evidence.auth_success_after_failures) risk += 40;
if (e.evidence && e.evidence.impossible_travel) risk += 40;
const _ct = e.attack_type || '';
if (_ct === 'cloud-identity') {
  const _o = e.observables || {};
  if (/createaccesskey|createuser|attach.*policy|createloginprofile|stoplogging|deletetrail|runinstances/i.test(_o.event_name || '')) risk += 25;
  if ((_o.error_code || '') !== '') risk += 10;
  const _pubip = !/^(10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.|127\.)/.test(e.src_ip || '');
  if (_pubip && (e.src_ip || '') !== '') risk += 5;
}

risk = Math.max(0, Math.min(100, risk));
const level = risk >= 75 ? 'HIGH' : (risk >= 40 ? 'MEDIUM' : 'LOW');
const ALLOW = ['127.0.0.1'];
const isPublic = _pub; // reuse v2 public test
const gates = {
  ti_bad: tis.some((t) => {
    const s = (t && t.sources) || {};
    const v = s.virustotal, a = s.abuseipdb;
    return !!((v && typeof v === 'object' && numOr(v.malicious) > 0) || (a && typeof a === 'object' && numOr(a.confidence) >= 70));
  }),
  success: !!(e.evidence && e.evidence.auth_success_after_failures),
  public_ip: isPublic, allowlisted: ALLOW.includes(e.src_ip)
};
const candidate = (risk >= 60 && !gates.allowlisted && (gates.ti_bad || gates.success)) ? ('block ' + e.src_ip) : null;
const _tib = Buffer.from(JSON.stringify(tis)).toString('base64'); return [{ json: Object.assign({}, e, { risk_score: risk, risk_level: level, gates, proposed_action: candidate, block_enabled: false, ti_b64: _tib }) }];

