// AuthCheck — replay protection for intake webhook
// Webhook output wraps body; manual path has no headers.
const j = $input.first().json;
if (!j.headers) {
  return [{ json: { ...j, auth_note: 'manual-bypass' } }];
}
const h = j.headers;
const tsRaw = h['x-soc-ts'] || h['X-SOC-TS'] || h['X-Soc-Ts'];
if (tsRaw === undefined || tsRaw === null || String(tsRaw).trim() === '') {
  throw new Error('stale webhook (possible replay)');
}
const ts = Number(String(tsRaw).trim());
if (!Number.isFinite(ts)) {
  throw new Error('stale webhook (possible replay)');
}
const now = Math.floor(Date.now() / 1000);
if (Math.abs(now - ts) > 300) {
  throw new Error('stale webhook (possible replay)');
}
return [{ json: { ...j, auth_note: 'ok' } }];
